const puml = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;

const result = { globals: {}, post: null };
// Probe for compression helpers
for (const g of ['pako','zlib','deflate','Compressor','CompressionStream','TextEncoder','btoa']) {
  try { result.globals[g] = typeof globalThis[g]; } catch(e){ result.globals[g] = 'err'; }
}
// Try POST raw text to public PlantUML server
try {
  const res = await fetch('https://www.plantuml.com/plantuml/svg/', {
    method: 'POST',
    headers: {'Content-Type': 'text/plain'},
    body: puml
  });
  result.post = { status: res.status, ct: res.headers.get('content-type') };
  const txt = await res.text();
  result.post.len = txt.length;
  result.post.head = txt.slice(0, 200);
} catch(e) {
  result.post = { error: String(e) };
}
return result;

